-- Golden King Balloon installer (generated by build_installer.py - edit the source files instead).
--
-- 1. Import GoldenKingBalloon.fbx and GoldenBalloonVFX.fbx (or the .glb files) with the 3D Importer.
-- 2. Run this file once: Model tab > Run Script, or paste it into the Command Bar.
--
-- It builds the GoldenKingBalloon model (ReplicatedStorage.GoldenKingBalloon, plus a preview in
-- the Workspace) and the scripts that put it on players. Running it again updates the scripts
-- and keeps your Config.

-- Change this to resize the balloon (and its aura): 0.8 = 20% smaller, 1.2 = 20% bigger.
local BALLOON_SCALE = 1.0

local SOURCES = {}
