SOURCES.Config = [=[
-- Golden King Balloon settings. Lives in ReplicatedStorage.GoldenKingBalloon.Config.
-- Safe to edit: re-running the installer keeps an existing Config.

local Config = {}

-- ---------------------------------------------------------------- who has it

-- A player wears the balloon while this attribute on their Player is "GoldenKingBalloon".
-- Your shop / inventory can set it, e.g. player:SetAttribute("EquippedBalloon", "GoldenKingBalloon"),
-- or call BalloonCosmetic.Equip(player) / .Unequip(player) from a server script.
Config.EquipAttribute = "EquippedBalloon"
-- Give it to everyone while you test in Studio (never in a live game).
Config.AutoEquipInStudio = true
-- Give it to every player in live games too (leave false if it's a shop item).
Config.AutoEquipEveryone = false

-- ---------------------------------------------------------------- where it floats

-- Studs from the player's HumanoidRootPart: X = to their right, Y = up, Z = behind them.
-- It's scaled with the character's height, so it sits the same on small and tall R15 avatars.
Config.Offset = Vector3.new(1.6, 3.6, 1.9)

Config.Float = {
	BobHeight = 0.18, -- studs up and down
	BobSpeed = 0.32, -- bobs per second
	Sway = 0.08, -- studs side to side
	SwaySpeed = 0.21,
	Tilt = 2.5, -- degrees of gentle rocking
	FollowStiffness = 40, -- how tightly it follows (lower = floatier, more lag when they start or stop)
	FollowDamping = 0.8, -- 1 = no overshoot, lower = a little bounce
	LeanIntoMotion = 0.012, -- how much it leans when the player runs (radians per stud/s)
	MaxLean = 12, -- degrees
	TurnSpeed = 7, -- how quickly it turns to face the way the player faces
	WingFlap = 3.5, -- degrees the wings rise and fall
	WingFold = 2.0, -- degrees they sweep back and forward
	WingSpeed = 0.42, -- flaps per second
	AnimateRange = 150, -- only animate balloons this close to the camera
	FloatAwayOnDeath = true, -- the balloon drifts up and away when its player dies
}

-- ---------------------------------------------------------------- how it looks

Config.Colors = {
	Balloon = Color3.fromRGB(255, 196, 30), -- only used if the balloon's texture didn't import
	Gold = Color3.fromRGB(255, 190, 40), -- crown and nozzle, if their texture didn't import
	Gem = Color3.fromRGB(255, 214, 40), -- the crown's gems
	Feather = Color3.fromRGB(255, 246, 225), -- wings, if their texture didn't import
	String = Color3.fromRGB(255, 250, 238),
	Light = Color3.fromRGB(255, 214, 120), -- the warm light round the balloon
}

-- "Metallic" (the imported glossy gold texture, the default) or "Glow" (bright Neon gold).
Config.BalloonStyle = "Metallic"
-- "Glass" (sparkling yellow gems, the default), "Neon" (glowing) or "Texture".
Config.GemStyle = "Glass"
Config.GemTransparency = 0.12
-- "Texture" (white / ivory feathers with gold bases, the default) or "Glow" (glowing white Neon).
Config.WingStyle = "Texture"

-- Optional: tie the string to the player's right hand with a curved beam instead of the
-- hanging string.
Config.TetherToHand = false

-- Paste uploaded image IDs here to override the imported textures, e.g. Sparkle = "rbxassetid://1".
-- Keys: Glow GlowGold GlowSoft Rays Trail Sparkle Star Mote Feather Swirl
Config.Textures = {}

Config.FallbackTextures = {
	Default = "rbxasset://textures/particles/sparkles_main.dds",
}

-- ---------------------------------------------------------------- the golden aura

Config.VFX = {
	Aura = true, -- the whole golden aura on / off
	Trails = true, -- the swirling golden energy trails
	TrailSpin = 22, -- degrees per second the trails turn round the balloon
	TrailFlow = 0.5, -- how fast light flows along them
	Streams = 2, -- bright streaks racing round the trails
	StreamSpeed = 0.45, -- laps per second
	Feathers = true, -- the golden feathers floating off it
	LightPulse = true, -- the glow gently breathes
}

return Config
]=]
SOURCES.BalloonCosmetic = [=[
-- Golden King Balloon: equip / attach API and the look (styles, colours, textures).
-- Lives in ReplicatedStorage.GoldenKingBalloon.BalloonCosmetic.
--
-- Server:
--   local Balloon = require(ReplicatedStorage.GoldenKingBalloon.BalloonCosmetic)
--   Balloon.Equip(player)      -- wears it now and after every respawn
--   Balloon.Unequip(player)
--   Balloon.IsEquipped(player)
-- Anywhere (e.g. a shop ViewportFrame):
--   local model = Balloon.Clone()   -- a fresh, anchored copy to show

local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")

local Folder = script.Parent
local Config = require(Folder:WaitForChild("Config"))

local Balloon = {}

Balloon.NAME = "GoldenKingBalloon"
Balloon.TAG = "GoldenKingBalloon" -- CollectionService tag on every worn balloon (the client animates these)

-- ---------------------------------------------------------------- looks

local function assets()
	return Folder:FindFirstChild("Assets")
end

-- Texture id for an effect key, and true when it had to fall back to a built-in texture.
function Balloon.Texture(key)
	local override = Config.Textures and Config.Textures[key]
	if override and override ~= "" then
		return override, false
	end
	local a = assets()
	local id = a and a:GetAttribute("Tex_" .. key)
	if typeof(id) == "string" and id ~= "" then
		return id, false
	end
	local fallbacks = Config.FallbackTextures or {}
	return fallbacks[key] or fallbacks.Default or "rbxasset://textures/particles/sparkles_main.dds", true
end

local function hasSurfaceAppearance(part)
	return part:FindFirstChildOfClass("SurfaceAppearance") ~= nil
end

-- The Glow style hides the imported SurfaceAppearance in a folder (so it can come back).
local function stashFolder(part)
	local f = part:FindFirstChild("Stash")
	if not f then
		f = Instance.new("Folder")
		f.Name = "Stash"
		f.Parent = part
	end
	return f
end

local function styleBalloon(part)
	if Config.BalloonStyle == "Glow" then
		part.Material = Enum.Material.Neon
		part.Color = Config.Colors.Balloon
		local sa = part:FindFirstChildOfClass("SurfaceAppearance")
		if sa then
			sa.Parent = stashFolder(part)
		end
		return
	end
	local stash = part:FindFirstChild("Stash")
	local sa = stash and stash:FindFirstChildOfClass("SurfaceAppearance")
	if sa then
		sa.Parent = part
	end
	if hasSurfaceAppearance(part) then
		part.Material = Enum.Material.SmoothPlastic
	else
		-- no PBR maps came in with the import: a glossy plastic over the painted gold texture
		part.Material = Enum.Material.SmoothPlastic
		part.Reflectance = 0.12
		if part.TextureID == "" then
			part.Color = Config.Colors.Balloon
		end
	end
end

local function styleGem(part)
	local style = Config.GemStyle or "Glass"
	local texture = part:GetAttribute("GemTexture") or ""
	part.Color = Config.Colors.Gem
	if style == "Neon" then
		part.Material = Enum.Material.Neon
		part.TextureID = ""
		part.Transparency = 0
	elseif style == "Texture" then
		part.Material = Enum.Material.SmoothPlastic
		part.TextureID = texture
		part.Transparency = 0
	else
		part.Material = Enum.Material.Glass
		part.TextureID = texture
		part.Transparency = Config.GemTransparency or 0.12
	end
end

local function styleFeather(part)
	local texture = part:GetAttribute("FeatherTexture") or ""
	if Config.WingStyle == "Glow" then
		part.Material = Enum.Material.Neon
		part.Color = Config.Colors.Feather
		part.TextureID = ""
	else
		part.Material = Enum.Material.SmoothPlastic
		part.TextureID = texture
		part.Color = texture ~= "" and Color3.new(1, 1, 1) or Config.Colors.Feather
	end
end

-- Applies Config (styles, colours, texture overrides, aura switches) to a balloon model.
function Balloon.ApplyStyle(model)
	local vfx = Config.VFX or {}
	local auraOn = vfx.Aura ~= false
	for _, inst in ipairs(model:GetDescendants()) do
		local kind = inst:GetAttribute("Kind")
		if inst:IsA("BasePart") and kind then
			if kind == "Balloon" then
				styleBalloon(inst)
			elseif kind == "Gem" then
				styleGem(inst)
			elseif kind == "Feather" then
				styleFeather(inst)
			elseif kind == "Gold" and not hasSurfaceAppearance(inst) and inst.TextureID == "" then
				inst.Color = Config.Colors.Gold
			elseif kind == "String" then
				inst.Color = Config.Colors.String
				inst.Transparency = Config.TetherToHand and 1 or 0
			end
		end
		local colorKey = inst:GetAttribute("ColorKey")
		if colorKey and Config.Colors[colorKey] and inst:IsA("Light") then
			inst.Color = Config.Colors[colorKey]
		end
		local key = inst:GetAttribute("TextureKey")
		if key and (inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam")) then
			inst.Texture = Balloon.Texture(key)
			local group = inst:GetAttribute("Group")
			local on = auraOn
			if group == "Trails" then
				on = on and vfx.Trails ~= false
			elseif group == "Feathers" then
				on = on and vfx.Feathers ~= false
			end
			inst.Enabled = on
			if inst:IsA("Beam") then
				inst.TextureSpeed = (inst:GetAttribute("FlowSign") or -1) * (vfx.TrailFlow or 0.5)
			end
		end
		if inst:IsA("PointLight") then
			inst.Enabled = auraOn
		end
	end
end

-- ---------------------------------------------------------------- attaching to a character

local function template()
	local t = Folder:FindFirstChild(Balloon.NAME)
	assert(t and t:IsA("Model"), "ReplicatedStorage.GoldenKingBalloon." .. Balloon.NAME .. " is missing (run the installer)")
	return t
end

-- A fresh copy of the balloon (anchored, not tagged), e.g. for a shop ViewportFrame.
function Balloon.Clone()
	local model = template():Clone()
	Balloon.ApplyStyle(model)
	return model
end

-- How much taller or shorter an R15 character is than the default (1 for R6).
local function heightScale(character)
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local root = character:FindFirstChild("HumanoidRootPart")
	if humanoid and root and humanoid.RigType == Enum.HumanoidRigType.R15 then
		return math.clamp((humanoid.HipHeight + root.Size.Y / 2) / 3, 0.4, 3)
	end
	return 1
end

function Balloon.Detach(character)
	local existing = character and character:FindFirstChild(Balloon.NAME)
	if existing then
		existing:Destroy()
	end
end

-- Puts the balloon on a character (server). Returns the model.
function Balloon.Attach(character)
	local root = character:WaitForChild("HumanoidRootPart", 10)
	local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 5)
	if not root then
		return nil
	end
	Balloon.Detach(character)
	local model = template():Clone()
	model.Name = Balloon.NAME
	local balloon = model.PrimaryPart or model:FindFirstChild("Balloon")
	for _, p in ipairs(model:GetDescendants()) do
		if p:IsA("BasePart") then
			p.Anchored = false
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.Massless = true
		end
	end
	local offset = Config.Offset * heightScale(character)
	local weld = Instance.new("Weld")
	weld.Name = "BalloonWeld"
	weld.Part0 = root
	weld.Part1 = balloon
	weld.C0 = CFrame.new(offset)
	weld.C1 = balloon.PivotOffset
	weld:SetAttribute("Offset", offset)
	model:PivotTo(root.CFrame * weld.C0)
	weld.Parent = balloon

	if Config.TetherToHand then
		local hand = character:FindFirstChild("RightHand") or character:FindFirstChild("Right Arm")
		local handAtt = hand and (hand:FindFirstChild("RightGripAttachment") or hand:FindFirstChildOfClass("Attachment"))
		local nozzle = balloon:FindFirstChild("Nozzle")
		if handAtt and nozzle then
			local beam = Instance.new("Beam")
			beam.Name = "Tether"
			beam.Attachment0 = nozzle
			beam.Attachment1 = handAtt
			beam.Width0, beam.Width1 = 0.06, 0.05
			beam.Color = ColorSequence.new(Config.Colors.String)
			beam.LightInfluence = 0.6
			beam.Segments = 16
			beam.CurveSize0 = -1.2
			beam.CurveSize1 = 0.6
			beam.FaceCamera = true
			beam.Parent = balloon
		end
	end

	Balloon.ApplyStyle(model)
	local owner = Players:GetPlayerFromCharacter(character)
	model:SetAttribute("OwnerUserId", owner and owner.UserId or 0)
	CollectionService:AddTag(model, Balloon.TAG)
	model.Parent = character

	-- when its player dies the balloon lets go: the client floats it up and away
	if humanoid then
		humanoid.Died:Once(function()
			if not model.Parent then
				return
			end
			if (Config.Float or {}).FloatAwayOnDeath ~= false then
				weld:Destroy() -- let go of the player before anchoring, so the body isn't held up
				for _, p in ipairs(model:GetDescendants()) do
					if p:IsA("BasePart") then
						p.Anchored = true
					end
				end
				model:SetAttribute("Released", workspace:GetServerTimeNow())
				task.delay(5, function()
					if model.Parent then
						model:Destroy()
					end
				end)
			end
		end)
	end
	return model
end

-- ---------------------------------------------------------------- equipping players

function Balloon.IsEquipped(player)
	return player:GetAttribute(Config.EquipAttribute) == Balloon.NAME
end

function Balloon.Equip(player)
	player:SetAttribute(Config.EquipAttribute, Balloon.NAME)
	if player.Character then
		Balloon.Attach(player.Character)
	end
end

function Balloon.Unequip(player)
	if Balloon.IsEquipped(player) then
		player:SetAttribute(Config.EquipAttribute, nil)
	end
	Balloon.Detach(player.Character)
end

return Balloon
]=]
SOURCES.Server = [=[
-- Golden King Balloon (server). Lives in ServerScriptService.GoldenBalloonServer.
-- Puts the balloon on every player who has it equipped, again after each respawn, and takes
-- it off when they unequip it. See BalloonCosmetic for the API your shop can call.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Folder = ReplicatedStorage:WaitForChild("GoldenKingBalloon")
local Config = require(Folder:WaitForChild("Config"))
local Balloon = require(Folder:WaitForChild("BalloonCosmetic"))

local function wearsIt(player)
	if Balloon.IsEquipped(player) then
		return true
	end
	if Config.AutoEquipEveryone then
		return true
	end
	return Config.AutoEquipInStudio == true and RunService:IsStudio()
end

local function onCharacter(player, character)
	if not wearsIt(player) then
		return
	end
	-- wait until the character has its root and is in the world
	character:WaitForChild("HumanoidRootPart", 10)
	if not character.Parent then
		character.AncestryChanged:Wait()
	end
	if character.Parent and player.Character == character and wearsIt(player) then
		Balloon.Attach(character)
	end
end

local function onPlayer(player)
	player.CharacterAdded:Connect(function(character)
		onCharacter(player, character)
	end)
	if player.Character then
		task.spawn(onCharacter, player, player.Character)
	end
	-- equipping / unequipping while alive
	player:GetAttributeChangedSignal(Config.EquipAttribute):Connect(function()
		local character = player.Character
		if not character then
			return
		end
		local worn = character:FindFirstChild(Balloon.NAME) ~= nil
		if wearsIt(player) and not worn then
			Balloon.Attach(character)
		elseif not wearsIt(player) and worn then
			Balloon.Detach(character)
		end
	end)
end

Players.PlayerAdded:Connect(onPlayer)
for _, player in ipairs(Players:GetPlayers()) do
	task.spawn(onPlayer, player)
end
]=]
SOURCES.Client = [=[
-- Golden King Balloon (client). Lives in StarterPlayerScripts.GoldenBalloonClient.
-- Animates every worn balloon on this screen: it floats beside its player with a gentle bob
-- and sway, follows them on a soft spring (leaning a little when they run), always stays
-- upright and faces the way they face (it never spins). The wings rise and fall slightly, the
-- golden energy trails turn round the balloon with bright streaks racing along them, and the
-- glow breathes. When its player dies, the balloon drifts up and away.

local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local Folder = ReplicatedStorage:WaitForChild("GoldenKingBalloon")
local Config = require(Folder:WaitForChild("Config"))
local Layout = require(Folder:WaitForChild("Layout"))
local Balloon = require(Folder:WaitForChild("BalloonCosmetic"))

local TAU = 2 * math.pi

-- Config value with a default, so a Config kept from an older install still works.
local function opt(group, key, default)
	local t = Config[group]
	local v = t and t[key]
	if v == nil then
		return default
	end
	return v
end

local function ns(points)
	local keys = {}
	for _, p in ipairs(points) do
		table.insert(keys, NumberSequenceKeypoint.new(p[1], p[2]))
	end
	return NumberSequence.new(keys)
end

local states = {}

-- ---------------------------------------------------------------- streams

-- Bright streaks racing round the energy trails (client-only trails in the EnergyTrails part).
local function makeStreams(st)
	local part = st.trails
	local origin = part and part:FindFirstChild("Origin")
	local vfx = Config.VFX or {}
	if not origin or vfx.Aura == false or vfx.Trails == false then
		return
	end
	local orbits = Layout.TrailOrbits or {}
	local count = math.max(0, math.floor(opt("VFX", "Streams", 2)))
	for i = 1, math.min(count, 6) do
		local raw = orbits[(i - 1) % math.max(1, #orbits) + 1]
		if raw and #raw > 2 then
			local path = {}
			for _, p in ipairs(raw) do
				table.insert(path, origin.CFrame:PointToWorldSpace(Vector3.new(p[1], p[2], p[3]) * st.scale))
			end
			local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
			a0.Name, a1.Name = "Stream" .. i .. "A", "Stream" .. i .. "B"
			a0.Parent, a1.Parent = part, part
			local trail = Instance.new("Trail")
			trail.Name = "Stream" .. i
			trail.Attachment0, trail.Attachment1 = a0, a1
			trail.Texture = Balloon.Texture("Trail")
			trail.TextureMode = Enum.TextureMode.Stretch
			trail.Lifetime = 0.45
			trail.MinLength = 0.02
			trail.FaceCamera = true
			trail.LightEmission = 1
			trail.LightInfluence = 0
			trail.WidthScale = ns({ { 0, 1 }, { 1, 0.1 } })
			trail.Transparency = ns({ { 0, 0 }, { 1, 1 } })
			trail.Parent = part
			table.insert(st.streams, {
				a0 = a0,
				a1 = a1,
				trail = trail,
				path = path,
				phase = (i - 1) / math.max(1, count),
				dir = i % 2 == 0 and -1 or 1,
			})
		end
	end
end

local function onLoop(path, s)
	local n = #path
	local x = (s % 1) * n
	local k = math.floor(x)
	local a, b = path[k % n + 1], path[(k + 1) % n + 1]
	return a:Lerp(b, x - k)
end

-- ---------------------------------------------------------------- tracking balloons

local function untrack(model)
	local st = states[model]
	if not st then
		return
	end
	states[model] = nil
	for _, s in ipairs(st.streams) do
		s.trail:Destroy()
		s.a0:Destroy()
		s.a1:Destroy()
	end
end

local function track(model)
	if states[model] or not model:IsDescendantOf(Workspace) then
		return
	end
	task.spawn(function()
		local balloon = model:WaitForChild("Balloon", 10)
		local weld = balloon and balloon:WaitForChild("BalloonWeld", 10)
		if not weld or states[model] or not model.Parent then
			return
		end
		local vfx = model:FindFirstChild("VFX")
		local trails = vfx and vfx:FindFirstChild("EnergyTrails")
		local aura = vfx and vfx:FindFirstChild("GoldenAura")
		local st = {
			model = model,
			balloon = balloon,
			weld = weld,
			offset = weld:GetAttribute("Offset") or weld.C0.Position,
			phase = math.random() * 10,
			scale = model:GetAttribute("BalloonScale") or 1,
			hinges = {},
			trails = trails,
			spin = trails and trails:FindFirstChild("TrailSpin"),
			light = aura and aura:FindFirstChildOfClass("PointLight"),
			streams = {},
		}
		for _, name in ipairs({ "LeftWing", "RightWing" }) do
			local wing = model:FindFirstChild(name)
			local hinge = wing and wing:FindFirstChild("WingHinge")
			if hinge and hinge:IsA("Weld") then
				table.insert(st.hinges, { weld = hinge, base = hinge.C0, side = name == "LeftWing" and -1 or 1 })
			end
		end
		if st.spin then
			st.spinBase = st.spin.C0
		end
		if st.light then
			st.lightBase = st.light.Brightness
		end
		makeStreams(st)
		states[model] = st
	end)
end

CollectionService:GetInstanceAddedSignal(Balloon.TAG):Connect(track)
CollectionService:GetInstanceRemovedSignal(Balloon.TAG):Connect(untrack)
for _, model in ipairs(CollectionService:GetTagged(Balloon.TAG)) do
	track(model)
end

-- ---------------------------------------------------------------- animation

local function float(st, dt, t)
	local weld = st.weld
	local root = weld.Part0
	if not (weld.Parent and root and root.Parent) then
		return
	end
	local F = Config.Float or {}
	-- face the way the player faces, but stay upright (only their turn, never their tilt)
	local look = root.CFrame.LookVector
	local flat = Vector3.new(look.X, 0, look.Z)
	if flat.Magnitude > 1e-3 then
		st.facing = flat.Unit
	end
	local facing = CFrame.lookAt(Vector3.zero, st.facing or Vector3.new(0, 0, -1))
	st.rot = st.rot and st.rot:Lerp(facing, 1 - math.exp(-dt * (F.TurnSpeed or 7))) or facing

	-- where it wants to be: beside the player, bobbing and swaying
	local bob = math.sin(t * TAU * (F.BobSpeed or 0.32)) * (F.BobHeight or 0.18)
	local sway = math.sin(t * TAU * (F.SwaySpeed or 0.21)) * (F.Sway or 0.08)
	local target = root.Position + st.rot:VectorToWorldSpace(st.offset + Vector3.new(sway, bob, 0))

	-- follow on a soft spring (snaps if the player teleports). The spring also matches the
	-- player's speed, so it only lags while they speed up, stop or turn, not all the time.
	if not st.pos or (st.pos - target).Magnitude > 25 then
		st.pos, st.vel, st.lastTarget = target, Vector3.zero, target
	end
	local targetVel = (target - (st.lastTarget or target)) / math.max(dt, 1e-3)
	if targetVel.Magnitude > 120 then
		targetVel = Vector3.zero
	end
	st.lastTarget = target
	local k = F.FollowStiffness or 40
	local c = 2 * math.sqrt(k) * (F.FollowDamping or 0.8)
	local steps = math.max(1, math.ceil(dt * 120))
	local h = dt / steps
	for _ = 1, steps do
		st.vel += ((target - st.pos) * k + (targetVel - st.vel) * c) * h
		st.pos += st.vel * h
	end

	-- lean into the motion like a balloon on a string (the top trails behind), plus gentle rocking
	local rel = st.rot:VectorToObjectSpace(st.vel)
	local lean = F.LeanIntoMotion or 0.012
	local maxLean = math.rad(F.MaxLean or 12)
	local tilt = math.rad(F.Tilt or 2.5)
	local pitch = math.clamp(-rel.Z * lean, -maxLean, maxLean) + math.sin(t * 0.83) * tilt * 0.6
	local roll = math.clamp(rel.X * lean, -maxLean, maxLean) + math.sin(t * 0.61 + 1.3) * tilt
	local world = CFrame.new(st.pos) * st.rot * CFrame.Angles(pitch, 0, roll)
	weld.C0 = root.CFrame:ToObjectSpace(world)

	-- the wings rise and fall a little
	local w = t * TAU * (F.WingSpeed or 0.42)
	local flap = math.sin(w) * math.rad(F.WingFlap or 3.5)
	local fold = math.sin(w - 0.8) * math.rad(F.WingFold or 2)
	for _, hinge in ipairs(st.hinges) do
		if hinge.weld.Parent then
			hinge.weld.C0 = hinge.base * CFrame.Angles(0, hinge.side * fold, flap)
		end
	end
end

local function aura(st, now)
	local vfx = Config.VFX or {}
	if st.spin and st.spin.Parent and st.spinBase then
		st.spin.C0 = st.spinBase * CFrame.Angles(0, math.rad(vfx.TrailSpin or 22) * now % TAU, 0)
	end
	local speed = vfx.StreamSpeed or 0.45
	for _, s in ipairs(st.streams) do
		local p = s.dir * now * speed + s.phase
		local w = 0.07 * st.scale
		local pos = onLoop(s.path, p)
		s.a0.Position = pos - Vector3.yAxis * w * 0.5
		s.a1.Position = pos + Vector3.yAxis * w * 0.5
	end
	if st.light and vfx.LightPulse ~= false then
		st.light.Brightness = st.lightBase * (0.85 + 0.15 * math.sin(now * 2.1))
	end
end

-- after its player dies the server lets go of it: drift up and away, then fade
local function release(st, now)
	if not st.released then
		st.released = { start = now, pivot = st.model:GetPivot() }
		for _, s in ipairs(st.streams) do
			s.trail.Enabled = false
		end
		for _, d in ipairs(st.model:GetDescendants()) do
			if d:IsA("ParticleEmitter") then
				d.Rate = d.Rate * 0.4
			end
		end
	end
	local e = now - st.released.start
	local rise = e * 2.4 + e * e * 0.5
	local drift = Vector3.new(math.sin(e * 1.3) * 0.4, rise, 0)
	st.model:PivotTo(st.released.pivot * CFrame.Angles(0, 0, math.sin(e * 1.7) * 0.08) + drift)
	local fade = math.clamp((e - 2.6) / 2, 0, 1)
	for _, d in ipairs(st.model:GetDescendants()) do
		if d:IsA("BasePart") then
			d.LocalTransparencyModifier = fade
		end
	end
end

RunService.RenderStepped:Connect(function(dt)
	dt = math.min(dt, 0.1)
	local now = os.clock()
	local cam = Workspace.CurrentCamera
	local range = opt("Float", "AnimateRange", 150)
	for model, st in pairs(states) do
		if not model.Parent then
			untrack(model)
			continue
		end
		if model:GetAttribute("Released") then
			if opt("Float", "FloatAwayOnDeath", true) then
				release(st, now)
			end
			continue
		end
		local near = cam ~= nil and (cam.CFrame.Position - st.balloon.Position).Magnitude < range
		if near then
			float(st, dt, now + st.phase)
			aura(st, now)
		else
			st.pos, st.lastTarget = nil, nil -- snap back into place when it comes into range again
		end
	end
end)
